+        name: String(o.name),
+        head_sha: String(o.headSha),
+        status: String(o.status),
+        output: {
+            title: String(o.title),
+            summary: truncateCheckRunSummary(o.summary)
+        }
+    };
+    if (o.conclusion) body.conclusion = String(o.conclusion);
